// ExtractEdges extracts graph links from TriggerDefinition.
func (x *TriggerDefinition) ExtractEdges(project string) ([]json.RawMessage, error) {
	var edges []json.RawMessage
	if x == nil || x.ID == nil {
		return edges, nil
	}
	id := *x.ID
	sourceType := "TriggerDefinition"
	projectJSON := strconv.Quote(project)
	_ = id
	_ = sourceType
	_ = projectJSON
	var seen map[string]struct{}
	_ = seen
	if x.Data != nil {
		for _, item_3_x_Data := range x.Data {
			if item_3_x_Data != nil {
				if item_3_x_Data.SubjectReference != nil {
					if item_3_x_Data.SubjectReference.Reference != nil {
						refVal := *item_3_x_Data.SubjectReference.Reference
						refType, targetID, ok := splitFHIRReference(refVal)
						if ok {
							if refType == "Group" {
								forwardKey := getEdgeUUID(targetID, id, "data_subjectReference")
								if seen == nil {
									seen = make(map[string]struct{}, 4)
								}
								if _, exists := seen[forwardKey]; !exists {
									seen[forwardKey] = struct{}{}
									edges = append(edges, buildEdgeRawJSON(
										forwardKey,
										collectionID(sourceType, id),
										collectionID("subjectReference", targetID),
										"data_subjectReference",
										projectJSON,
										sourceType,
										"subjectReference",
									))
								}
								backrefKey := getEdgeUUID(id, targetID, "data_requirement")
								if seen == nil {
									seen = make(map[string]struct{}, 4)
								}
								if _, exists := seen[backrefKey]; !exists {
									seen[backrefKey] = struct{}{}
									edges = append(edges, buildEdgeRawJSON(
										backrefKey,
										collectionID(sourceType, targetID),
										collectionID("requirement", id),
										"data_requirement",
										projectJSON,
										sourceType,
										"requirement",
									))
								}
							}
						}
					}
				}
			}
		}
	}
	return edges, nil
}

